-- Migration: 087_evaluation_reward_finance_closure.sql
-- 科研绩效奖励支付批次、财务/工资回写流水和对账闭环。
-- 本迁移只建立待提交批次和不可变审计结构，不插入任何支付或示例凭证。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研评价奖励支付批次" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "批次号" varchar(100) NOT NULL,
    "评价年度" integer NOT NULL,
    "人员编号" integer NOT NULL,
    "财务系统代码" varchar(50) NOT NULL DEFAULT '待配置',
    "财务请求幂等键" varchar(150) NOT NULL,
    "外部批次号" varchar(150),
    "状态" varchar(20) NOT NULL DEFAULT '待提交',
    "对账状态" varchar(20) NOT NULL DEFAULT '未对账',
    "奖励笔数" integer NOT NULL DEFAULT 0,
    "奖励总额" numeric(14,2) NOT NULL DEFAULT 0,
    "成功笔数" integer NOT NULL DEFAULT 0,
    "失败笔数" integer NOT NULL DEFAULT 0,
    "最后错误" varchar(2000),
    "提交时间" timestamp without time zone,
    "回写时间" timestamp without time zone,
    "对账时间" timestamp without time zone,
    "创建人编号" integer NOT NULL,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价奖励支付批次" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价奖励支付批次_批次号" UNIQUE ("批次号"),
    CONSTRAINT "uq_科研评价奖励支付批次_幂等键" UNIQUE ("财务请求幂等键"),
    CONSTRAINT "ck_科研评价奖励支付批次_年度" CHECK ("评价年度" BETWEEN 2000 AND 2200),
    CONSTRAINT "ck_科研评价奖励支付批次_金额" CHECK ("奖励总额" >= 0),
    CONSTRAINT "ck_科研评价奖励支付批次_计数" CHECK ("奖励笔数" >= 0 AND "成功笔数" >= 0 AND "失败笔数" >= 0 AND "成功笔数" + "失败笔数" <= "奖励笔数"),
    CONSTRAINT "ck_科研评价奖励支付批次_状态" CHECK ("状态" IN ('待提交','已提交财务','回写中','部分成功','已完成','已失败','已取消')),
    CONSTRAINT "ck_科研评价奖励支付批次_对账" CHECK ("对账状态" IN ('未对账','对账中','一致','不一致')),
    CONSTRAINT "ck_科研评价奖励支付批次_凭据文本" CHECK ("批次号" !~* '(模拟|样例|demo|sample|hrp[-_ ]?voucher|1580)' AND "财务请求幂等键" !~* '(模拟|样例|demo|sample|hrp[-_ ]?voucher|1580)')
);
CREATE INDEX IF NOT EXISTS "ix_科研评价奖励支付批次_状态" ON "科研评价奖励支付批次" ("状态", "对账状态", "评价年度", "人员编号");

ALTER TABLE "科研评价奖励"
    ADD COLUMN IF NOT EXISTS "支付批次编号" bigint,
    ADD COLUMN IF NOT EXISTS "支付失败原因" varchar(1000),
    ADD COLUMN IF NOT EXISTS "支付尝试次数" integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS "最后支付尝试时间" timestamp without time zone,
    ADD COLUMN IF NOT EXISTS "最后对账时间" timestamp without time zone;
ALTER TABLE "科研评价奖励" DROP CONSTRAINT IF EXISTS "fk_科研评价奖励_支付批次";
ALTER TABLE "科研评价奖励" ADD CONSTRAINT "fk_科研评价奖励_支付批次" FOREIGN KEY ("支付批次编号") REFERENCES "科研评价奖励支付批次" ("编号");
ALTER TABLE "科研评价奖励" DROP CONSTRAINT IF EXISTS "ck_科研评价奖励_支付尝试次数";
ALTER TABLE "科研评价奖励" ADD CONSTRAINT "ck_科研评价奖励_支付尝试次数" CHECK ("支付尝试次数" >= 0);
CREATE INDEX IF NOT EXISTS "ix_科研评价奖励_支付批次" ON "科研评价奖励" ("支付批次编号", "支付状态", "财务回写状态");

CREATE TABLE IF NOT EXISTS "科研评价奖励支付流水" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY,
    "奖励编号" bigint NOT NULL,
    "支付批次编号" bigint NOT NULL,
    "事件类型" varchar(20) NOT NULL,
    "幂等键" varchar(180) NOT NULL,
    "外部流水号" varchar(150),
    "财务凭证号" varchar(100),
    "支付凭证号" varchar(100),
    "错误原因" varchar(1000),
    "快照JSON" jsonb,
    "操作人编号" integer NOT NULL,
    "建立时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "pk_科研评价奖励支付流水" PRIMARY KEY ("编号"),
    CONSTRAINT "uq_科研评价奖励支付流水_幂等键" UNIQUE ("幂等键"),
    CONSTRAINT "fk_科研评价奖励支付流水_奖励" FOREIGN KEY ("奖励编号") REFERENCES "科研评价奖励" ("编号"),
    CONSTRAINT "fk_科研评价奖励支付流水_批次" FOREIGN KEY ("支付批次编号") REFERENCES "科研评价奖励支付批次" ("编号"),
    CONSTRAINT "ck_科研评价奖励支付流水_事件" CHECK ("事件类型" IN ('批次创建','提交财务','重试','回写成功','回写失败','对账一致','对账不一致','冲正')),
    CONSTRAINT "ck_科研评价奖励支付流水_成功凭据" CHECK ("事件类型" <> '回写成功' OR (NULLIF(BTRIM("财务凭证号"), '') IS NOT NULL AND NULLIF(BTRIM("支付凭证号"), '') IS NOT NULL)),
    CONSTRAINT "ck_科研评价奖励支付流水_凭据文本" CHECK (COALESCE("幂等键", '') !~* '(模拟|样例|demo|sample|hrp[-_ ]?voucher|1580)' AND COALESCE("外部流水号", '') !~* '(模拟|样例|demo|sample|hrp[-_ ]?voucher|1580)' AND COALESCE("财务凭证号", '') !~* '(模拟|样例|demo|sample|hrp[-_ ]?voucher|1580)' AND COALESCE("支付凭证号", '') !~* '(模拟|样例|demo|sample|hrp[-_ ]?voucher|1580)')
);
CREATE INDEX IF NOT EXISTS "ix_科研评价奖励支付流水_奖励" ON "科研评价奖励支付流水" ("奖励编号", "建立时间");
CREATE INDEX IF NOT EXISTS "ix_科研评价奖励支付流水_批次" ON "科研评价奖励支付流水" ("支付批次编号", "事件类型", "建立时间");

CREATE OR REPLACE FUNCTION "fn_科研评价奖励支付流水_禁止改写"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION '科研评价奖励支付流水为不可变审计记录，只允许追加重试、回写或冲正事件' USING ERRCODE = '55000';
END;
$$;
DROP TRIGGER IF EXISTS "trg_科研评价奖励支付流水_禁止改写" ON "科研评价奖励支付流水";
CREATE TRIGGER "trg_科研评价奖励支付流水_禁止改写"
BEFORE UPDATE OR DELETE ON "科研评价奖励支付流水"
FOR EACH ROW EXECUTE FUNCTION "fn_科研评价奖励支付流水_禁止改写"();

CREATE OR REPLACE FUNCTION "fn_科研评价奖励支付_状态约束"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW."支付状态" = '已支付' THEN
        IF NEW."财务回写状态" <> '已回写'
           OR NULLIF(BTRIM(NEW."财务凭证号"), '') IS NULL
           OR NULLIF(BTRIM(NEW."支付凭证号"), '') IS NULL
           OR NEW."支付批次编号" IS NULL THEN
            RAISE EXCEPTION '奖励标记已支付必须绑定支付批次并提供财务回写和支付凭证' USING ERRCODE = '23514';
        END IF;
    END IF;
    IF TG_OP = 'UPDATE' AND OLD."支付状态" = '已支付' AND NEW."支付状态" <> '已支付' THEN
        RAISE EXCEPTION '已支付奖励不能回退，请通过追加冲正事件处理' USING ERRCODE = '55000';
    END IF;
    IF NEW."支付状态" = '支付失败' AND NULLIF(BTRIM(NEW."支付失败原因"), '') IS NULL THEN
        RAISE EXCEPTION '支付失败必须记录失败原因，重试只能追加新的流水事件' USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trg_科研评价奖励支付_状态约束" ON "科研评价奖励";
CREATE TRIGGER "trg_科研评价奖励支付_状态约束"
BEFORE INSERT OR UPDATE OF "支付状态", "财务回写状态", "财务凭证号", "支付凭证号", "支付批次编号", "支付失败原因"
ON "科研评价奖励"
FOR EACH ROW EXECUTE FUNCTION "fn_科研评价奖励支付_状态约束"();

CREATE OR REPLACE FUNCTION "fn_科研评价奖励支付批次_刷新状态"()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    batch_id bigint;
    total_count integer;
    success_count integer;
    failed_count integer;
BEGIN
    batch_id := COALESCE(NEW."支付批次编号", OLD."支付批次编号");
    IF batch_id IS NULL THEN RETURN NEW; END IF;
    SELECT COUNT(*)::integer,
           COUNT(*) FILTER (WHERE "支付状态" = '已支付')::integer,
           COUNT(*) FILTER (WHERE "支付状态" = '支付失败')::integer
      INTO total_count, success_count, failed_count
      FROM "科研评价奖励"
     WHERE "支付批次编号" = batch_id;
    UPDATE "科研评价奖励支付批次"
       SET "奖励笔数" = total_count,
           "成功笔数" = success_count,
           "失败笔数" = failed_count,
           "状态" = CASE
               WHEN success_count = total_count AND total_count > 0 THEN '已完成'
               WHEN failed_count = total_count AND total_count > 0 THEN '已失败'
               WHEN success_count > 0 OR failed_count > 0 THEN '部分成功'
               ELSE "状态"
           END,
           "回写时间" = CASE WHEN success_count > 0 OR failed_count > 0 THEN COALESCE("回写时间", CURRENT_TIMESTAMP) ELSE "回写时间" END,
           "更新时间" = CURRENT_TIMESTAMP
     WHERE "编号" = batch_id;
    RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS "trg_科研评价奖励支付批次_刷新状态" ON "科研评价奖励";
CREATE TRIGGER "trg_科研评价奖励支付批次_刷新状态"
AFTER INSERT OR UPDATE OF "支付状态", "支付批次编号", "财务回写状态"
ON "科研评价奖励"
FOR EACH ROW EXECUTE FUNCTION "fn_科研评价奖励支付批次_刷新状态"();

UPDATE "系统迁移版本"
   SET "版本" = 87,
       "脚本" = '087_evaluation_reward_finance_closure.sql',
       "检查摘要" = '增加奖励支付批次、不可变财务回写流水、失败重试和对账状态约束',
       "应用时间" = CURRENT_TIMESTAMP
 WHERE "编号" = 1;
COMMIT;
